FILE:.github/workflows/sql-faker-fuzz.yml
name: Fuzz (sql-faker)

on:
  schedule:
    - cron: '0 3 * * *'
  workflow_dispatch:
    inputs:
      max_runs:
        description: 'Max fuzzing iterations'
        default: '10000'
        type: string

permissions:
  actions: read
  contents: read
  issues: write

jobs:
  syntax:
    name: Syntax / ${{ matrix.target.name }}
    runs-on: ubuntu-latest
    strategy:
      fail-fast: false
      matrix:
        target:
          - { name: mysql-syntax, script: fuzz_mysql_syntax.php, corpus: mysql, extensions: "mbstring, pcntl, pdo, pdo_mysql" }
          - { name: pg-syntax, script: fuzz_pg_syntax.php, corpus: pg, extensions: "mbstring, pcntl, pdo, pdo_pgsql" }
          - { name: sqlite-syntax, script: fuzz_sqlite_syntax.php, corpus: sqlite, extensions: "mbstring, pcntl, pdo, pdo_sqlite" }
    defaults:
      run:
        working-directory: packages/sql-faker
    steps:
      - uses: actions/checkout@v6

      - uses: shivammathur/setup-php@v2
        with:
          php-version: '8.5'
          extensions: ${{ matrix.target.extensions }}
          coverage: none

      - uses: ramsey/composer-install@v3
        with:
          working-directory: packages/sql-faker

      - uses: actions/cache/restore@v5
        with:
          path: packages/sql-faker/fuzz/corpus/${{ matrix.target.corpus }}
          key: fuzz-sql-faker-${{ matrix.target.corpus }}-${{ github.run_id }}
          restore-keys: |
            fuzz-sql-faker-${{ matrix.target.corpus }}-

      - name: fuzzer
        run: |
          vendor/bin/php-fuzzer fuzz fuzz/${{ matrix.target.script }} \
            fuzz/corpus/${{ matrix.target.corpus }}/ \
            --max-runs=${{ inputs.max_runs || '10000' }}

      - if: always()
        uses: actions/cache/save@v5
        with:
          path: packages/sql-faker/fuzz/corpus/${{ matrix.target.corpus }}
          key: fuzz-sql-faker-${{ matrix.target.corpus }}-${{ github.run_id }}

      - if: ${{ always() && hashFiles('packages/sql-faker/crash-*') != '' }}
        uses: actions/upload-artifact@v6
        with:
          name: fuzz-crashes-sql-faker-${{ matrix.target.name }}
          path: packages/sql-faker/crash-*

  notify:
    name: Notify on crash
    runs-on: ubuntu-latest
    needs: [syntax]
    steps:
      - uses: actions/github-script@v8
        with:
          script: |
